import type { ModelExecution } from "./models.js";
import type { DayKey } from "./time.js";
import type { BriefFallbackReason } from "./today.js";

export const BRIEF_REF_KINDS = ["todo", "mail", "event", "assignment", "github", "habit", "project"] as const;
export type BriefRefKind = (typeof BRIEF_REF_KINDS)[number];

/**
 * The hero brief (SPEC §4.2), one row per local day in daily_briefs. The H1 is
 * always rule-generated by the core; this is only the sentence under it: at
 * most 2 sentences and 80 CJK characters, naming the most important item
 * first, then the next time-bound thing, then optionally the largest free
 * slot, never contradicting `counts`. source "rule" is the deterministic
 * fallback (shared/today-logic.ts ruleBrief), so Today never depends on a model.
 */
export interface DailyBrief {
  day: DayKey;
  source: "ai" | "rule";
  text: string;
  /** Items the text names, for highlighting or deep links. */
  refs?: { kind: BriefRefKind; id: string }[];
  generatedAt: string;
  modelExecution?: ModelExecution;
  /**
   * source "rule" only: why the AI brief for this day failed (SPEC §4.2
   * fallback note). Stored so the failure is shown, and not retried on every
   * page open, until 重試, the next automatic run or the next day.
   */
  failure?: BriefFallbackReason;
  /** A transient failure (a usage limit, a dropped connection): first open retries once after this instant. */
  retryAfter?: string;
}

export const BRIEF_LIMITS = { text: 80, sentences: 2, refs: 5 } as const;
